mapper.select:
WITH snapshots AS (
    SELECT tenant_id,session_id,event_id,runtime_run_id,session_sequence,event_type,payload::text AS payload_json,created_at,
           min(session_sequence) OVER(PARTITION BY payload #>> '{data,message_id}') AS first_sequence,
           min(created_at) OVER(PARTITION BY payload #>> '{data,message_id}') AS first_created_at,
           row_number() OVER(PARTITION BY payload #>> '{data,message_id}' ORDER BY (payload #>> '{data,message_version}')::bigint DESC,session_sequence DESC) AS snapshot_rank
    FROM nw_chat_session_outbox WHERE tenant_id=#{tenant} AND session_id=#{session} AND session_sequence <=#{through}
      AND event_type IN('message.delta','message.card','message.card.update') AND payload #>> '{data,message_id}' IS NOT NULL
)
SELECT tenant_id,session_id,event_id,runtime_run_id,session_sequence,event_type,payload_json,created_at,first_sequence,first_created_at
FROM snapshots WHERE snapshot_rank=1 AND first_sequence < #{before} ORDER BY first_sequence DESC LIMIT #{limit}
